#!/usr/bin/env bash
# A Samba AD DC in a container on the test VM: the client's AD for the Azure run.
#   samba-dc.sh REALM     (stdin: the administrator's, the join account's and the test
#                          user's passwords, one per line; generated by the harness)
# Users and groups follow dev/scripts/dc-provision.sh's shape: a join account, the
# "filer admins" group, and an AD user with POSIX attributes (idmap_ad) for the exit's SMB
# and NFS steps. The passwords go to $R/secrets.json (root, 0600) for exit.sh.
set -euo pipefail
REALM=${1:?realm}
R=/srv/ofreal
read -r ADMIN_PW
read -r JOIN_PW
read -r USER_PW
read -r OTHER_PW
DOMAIN=$(echo "${REALM%%.*}" | tr '[:lower:]' '[:upper:]')
umask 077
printf '{"realm": "%s", "admin": "%s", "join": "%s", "user": "%s", "other": "%s"}\n' \
  "$REALM" "$ADMIN_PW" "$JOIN_PW" "$USER_PW" "$OTHER_PW" >"$R/secrets.json"
if docker inspect ofreal-dc >/dev/null 2>&1; then
  echo '{"ok": true, "dc": "already running"}'
  exit 0
fi
docker run -d --name ofreal-dc --hostname dc1 --privileged --network ofreal --ip 172.30.0.10 \
  --dns 127.0.0.1 ubuntu:24.04 sleep infinity >/dev/null
dc() { docker exec -i ofreal-dc "$@"; }
dc bash -c 'export DEBIAN_FRONTEND=noninteractive; apt-get update -q && apt-get install -y -q samba-ad-dc krb5-user winbind smbclient >/dev/null'
dc bash -c "rm -f /etc/samba/smb.conf && samba-tool domain provision --realm=$REALM --domain=$DOMAIN \
  --server-role=dc --dns-backend=SAMBA_INTERNAL --use-rfc2307 --adminpass='$ADMIN_PW' \
  --option='dns forwarder = 168.63.129.16' >/dev/null && samba -D"
sleep 5
dc samba-tool user create ofreal-join "$JOIN_PW" >/dev/null
dc samba-tool group addmembers "Domain Admins" ofreal-join >/dev/null
dc samba-tool group add "filer admins" --gid-number=30000 --nis-domain="$DOMAIN" >/dev/null
dc samba-tool group add Proj-Writers --gid-number=30001 --nis-domain="$DOMAIN" >/dev/null
dc samba-tool user create geo-writer "$USER_PW" --uid-number=20002 --gid-number=30001 \
  --login-shell=/bin/bash --unix-home=/home/geo-writer --nis-domain="$DOMAIN" >/dev/null
dc samba-tool group addmembers Proj-Writers geo-writer >/dev/null
dc samba-tool group add Proj-Readers --gid-number=30002 --nis-domain="$DOMAIN" >/dev/null
dc samba-tool user create geo-reader "$OTHER_PW" --uid-number=20001 --gid-number=30002 \
  --login-shell=/bin/bash --unix-home=/home/geo-reader --nis-domain="$DOMAIN" >/dev/null
dc samba-tool group addmembers Proj-Readers geo-reader >/dev/null
dc samba-tool group add OmniFile-ArchiveAdmins --gid-number=30003 --nis-domain="$DOMAIN" >/dev/null
dc samba-tool group add OmniFile-DataStewards --gid-number=30004 --nis-domain="$DOMAIN" >/dev/null
dc samba-tool group addmembers "filer admins" ofreal-join >/dev/null
dc samba-tool group addunixattrs "Domain Users" 30010 >/dev/null
echo '{"ok": true, "dc": "provisioned", "realm": "'"$REALM"'"}'
